namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();
        foreach (var item in items)
        {
            if (item.OnHand < 0)
                continue;
            if (string.IsNullOrEmpty(item.Sku))
                continue;

            int orderQty = CalculateOrderQuantity(item, season);
            if (orderQty <= 0)
                continue;

            bool placed = supplier.PlaceOrder(item.Sku, orderQty);
            plan.Add(FormatResult(item.Sku, orderQty, placed));
        }
        return plan;
    }

    private static int CalculateOrderQuantity(StockItem item, int season)
    {
        int available = item.OnHand - item.Reserved;
        if (available > item.ReorderPoint) return 0;

        int deficit = item.ReorderPoint - available;
        int quantity = deficit <= 0 ? 0
            : deficit < 10 ? 10
            : deficit < 100 ? deficit
            : deficit + 50;

        return season switch
        {
            4 when quantity > 0 => checked(quantity * 3 / 2),
            1 => quantity / 2,
            _ => quantity
        };
    }

    private static string FormatResult(string sku, int quantity, bool placed) =>
        !placed ? $"{sku}:FAILED" :
        quantity > 200 ? $"{sku}:LARGE:{quantity}" :
        $"{sku}:{quantity}";
}
